import { test, expect } from '@playwright/test';

test.describe('Freeze First Column on Horizontal Scroll', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the table page
    await page.goto('http://localhost:3000/table');

    // Wait for the table to load
    await page.waitForSelector('table', { timeout: 5000 });
  });

  test('should keep first column visible when scrolling horizontally to the right', async ({ page }) => {
    // Get the table container
    const tableContainer = page.locator('[role="region"]').first();

    // Verify the first column is visible initially
    const firstColumnHeader = page.getByRole('columnheader').first();
    await expect(firstColumnHeader).toBeVisible();

    // Get initial position of first column
    const initialBoundingBox = await firstColumnHeader.boundingBox();
    expect(initialBoundingBox).not.toBeNull();
    const initialLeftPosition = initialBoundingBox!.x;

    // Scroll the table horizontally to the right
    await tableContainer.evaluate((element) => {
      element.scrollLeft = 500;
    });

    // Wait for scroll to complete
    await page.waitForTimeout(500);

    // Verify first column is still visible
    await expect(firstColumnHeader).toBeVisible();

    // Get position after scroll
    const afterScrollBoundingBox = await firstColumnHeader.boundingBox();
    expect(afterScrollBoundingBox).not.toBeNull();
    const afterScrollLeftPosition = afterScrollBoundingBox!.x;

    // First column should remain at approximately the same position (frozen)
    expect(Math.abs(afterScrollLeftPosition - initialLeftPosition)).toBeLessThan(10);
  });

  test('should maintain first column position while scrolling through multiple columns', async ({ page }) => {
    // Get all column headers
    const columnHeaders = page.getByRole('columnheader');
    const columnCount = await columnHeaders.count();

    expect(columnCount).toBeGreaterThan(1);

    // Get the first column header
    const firstColumnHeader = page.getByRole('columnheader').first();
    const firstColumnText = await firstColumnHeader.textContent();

    // Get the table container
    const tableContainer = page.locator('[role="region"]').first();

    // Get initial position
    const initialBoundingBox = await firstColumnHeader.boundingBox();
    const initialLeftPosition = initialBoundingBox!.x;

    // Scroll to the right multiple times
    for (let i = 0; i < 3; i++) {
      await tableContainer.evaluate((element) => {
        element.scrollLeft += 200;
      });
      await page.waitForTimeout(300);

      // Verify first column is still visible
      await expect(firstColumnHeader).toBeVisible();

      // Verify first column content hasn't changed
      const currentText = await firstColumnHeader.textContent();
      expect(currentText).toBe(firstColumnText);

      // Verify position remains frozen
      const currentBoundingBox = await firstColumnHeader.boundingBox();
      const currentLeftPosition = currentBoundingBox!.x;
      expect(Math.abs(currentLeftPosition - initialLeftPosition)).toBeLessThan(10);
    }
  });

  test('should apply frozen column styling to first column', async ({ page }) => {
    // Get the first column header
    const firstColumnHeader = page.getByRole('columnheader').first();

    // Check if the first column has frozen column styling
    const firstColumnParent = firstColumnHeader.locator('..');

    // Verify the column has sticky positioning or frozen class
    const computedStyle = await firstColumnHeader.evaluate((element) => {
      return window.getComputedStyle(element).position;
    });

    // The first column should have sticky or fixed positioning
    expect(['sticky', 'fixed']).toContain(computedStyle);
  });

  test('should scroll first column content vertically while keeping it frozen horizontally', async ({ page }) => {
    // Get the table container
    const tableContainer = page.locator('[role="region"]').first();

    // Get the first column header
    const firstColumnHeader = page.getByRole('columnheader').first();
    const initialHeaderBoundingBox = await firstColumnHeader.boundingBox();
    const initialHeaderLeftPosition = initialHeaderBoundingBox!.x;

    // Get first column cells
    const firstColumnCells = page.locator('tbody tr td:first-child');
    const cellCount = await firstColumnCells.count();

    expect(cellCount).toBeGreaterThan(0);

    // Scroll horizontally
    await tableContainer.evaluate((element) => {
      element.scrollLeft = 400;
    });
    await page.waitForTimeout(500);

    // Verify header position is frozen
    const afterHorizontalScrollHeaderBox = await firstColumnHeader.boundingBox();
    expect(Math.abs(afterHorizontalScrollHeaderBox!.x - initialHeaderLeftPosition)).toBeLessThan(10);

    // Scroll vertically
    await tableContainer.evaluate((element) => {
      element.scrollTop = 300;
    });
    await page.waitForTimeout(500);

    // Verify header position is still frozen horizontally
    const afterVerticalScrollHeaderBox = await firstColumnHeader.boundingBox();
    expect(Math.abs(afterVerticalScrollHeaderBox!.x - initialHeaderLeftPosition)).toBeLessThan(10);

    // Verify first column cells are still visible
    const visibleCells = await firstColumnCells.filter({ hasNot: page.locator('body > :hidden') }).count();
    expect(visibleCells).toBeGreaterThan(0);
  });

  test('should maintain first column visibility when table has horizontal overflow', async ({ page }) => {
    // Get the table container
    const tableContainer = page.locator('[role="region"]').first();

    // Check if table has horizontal overflow
    const hasHorizontalScroll = await tableContainer.evaluate((element) => {
      return element.scrollWidth > element.clientWidth;
    });

    expect(hasHorizontalScroll).toBe(true);

    // Get the first column
    const firstColumnHeader = page.getByRole('columnheader').first();
    const firstColumnCells = page.locator('tbody tr td:first-child');

    // Scroll to the end
    await tableContainer.evaluate((element) => {
      element.scrollLeft = element.scrollWidth;
    });
    await page.waitForTimeout(500);

    // Verify first column header is still visible
    await expect(firstColumnHeader).toBeVisible();

    // Verify at least one first column cell is visible
    const visibleCellCount = await firstColumnCells.count();
    expect(visibleCellCount).toBeGreaterThan(0);
  });
});
